from fastapi import FastAPI
import asyncio

app = FastAPI()

shared_cache = {}

@app.get("/data/{key}")
async def get_cached(key: str):
    if key not in shared_cache:
        shared_cache[key] = await fetch_data(key)
    return shared_cache[key]

async def fetch_data(key: str):
    await asyncio.sleep(1)
    return {"data": key}

